alter table profiles enable row level security; alter table categories enable row level security; alter table products enable row level security; alter table product_images enable row level security; alter table product_variants enable row level security; alter table tags enable row level security; alter table product_tags enable row level security; alter table wishlists enable row level security; alter table wishlist_items enable row level security; alter table carts enable row level security; alter table cart_items enable row level security; alter table shipping_zones enable row level security; alter table pricing_rules enable row level security; alter table orders enable row level security; alter table order_items enable row level security; alter table reviews enable row level security; alter table addresses enable row level security; alter table site_content enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin') $$;
create policy "public read active categories" on categories for select using(is_active or public.is_admin()); create policy "public read active products" on products for select using(is_active or public.is_admin()); create policy "public read product images" on product_images for select using(true); create policy "public read variants" on product_variants for select using(true); create policy "public read tags" on tags for select using(true); create policy "public read product tags" on product_tags for select using(true); create policy "public read approved reviews" on reviews for select using(approved or user_id=auth.uid() or public.is_admin());
create policy "own profile" on profiles for select using(id=auth.uid() or public.is_admin()); create policy "update own profile" on profiles for update using(id=auth.uid()); create policy "admin manage profiles" on profiles for all using(public.is_admin()) with check(public.is_admin());
create policy "own wishlist" on wishlists for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin()); create policy "own wishlist items" on wishlist_items for all using(exists(select 1 from wishlists w where w.id=wishlist_id and (w.user_id=auth.uid() or public.is_admin()))) with check(exists(select 1 from wishlists w where w.id=wishlist_id and (w.user_id=auth.uid() or public.is_admin())));
create policy "own carts" on carts for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin()); create policy "own cart items" on cart_items for all using(exists(select 1 from carts c where c.id=cart_id and (c.user_id=auth.uid() or public.is_admin()))) with check(exists(select 1 from carts c where c.id=cart_id and (c.user_id=auth.uid() or public.is_admin())));
create policy "own orders" on orders for select using(user_id=auth.uid() or public.is_admin()); create policy "own order items" on order_items for select using(exists(select 1 from orders o where o.id=order_id and (o.user_id=auth.uid() or public.is_admin()))); create policy "admin orders" on orders for all using(public.is_admin()) with check(public.is_admin()); create policy "admin order items" on order_items for all using(public.is_admin()) with check(public.is_admin());
create policy "own addresses" on addresses for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin()); create policy "reviews insert own" on reviews for insert with check(user_id=auth.uid()); create policy "reviews update own" on reviews for update using(user_id=auth.uid() or public.is_admin()); create policy "admin reviews" on reviews for all using(public.is_admin()) with check(public.is_admin());
create policy "public active shipping" on shipping_zones for select using(is_active or public.is_admin()); create policy "public active pricing" on pricing_rules for select using(is_active or public.is_admin()); create policy "admin categories" on categories for all using(public.is_admin()) with check(public.is_admin()); create policy "admin products" on products for all using(public.is_admin()) with check(public.is_admin()); create policy "admin images" on product_images for all using(public.is_admin()) with check(public.is_admin()); create policy "admin variants" on product_variants for all using(public.is_admin()) with check(public.is_admin()); create policy "admin tags" on tags for all using(public.is_admin()) with check(public.is_admin()); create policy "admin product tags" on product_tags for all using(public.is_admin()) with check(public.is_admin()); create policy "admin shipping" on shipping_zones for all using(public.is_admin()) with check(public.is_admin()); create policy "admin pricing" on pricing_rules for all using(public.is_admin()) with check(public.is_admin()); create policy "admin content" on site_content for all using(public.is_admin()) with check(public.is_admin()); create policy "public content" on site_content for select using(true);
